import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../../../Core/Resources/app_fonts.dart';import '../../../../../../Core/Resources/app_colors.dart';import '../../../../../../Config/Routes/route_name.dart';import '../../../../../../Core/Models/cart_itemes.dart';import '../../../../../../Core/Utils/Widget/Images/build_image.dart';import '../../../../../../generated/l10n.dart';import '../../../../../../main.dart';import '../Cubit/Cart/cart_cubit.dart';class BodyPageCartItems extends StatelessWidget {  const BodyPageCartItems(      {super.key, required this.cartItems, required this.local});  final List<Item>? cartItems;  final S local;  @override  Widget build(BuildContext context) {    return ListView(children: [      ...List.generate(cartItems?.length ?? 0, (index) {        final items = cartItems?[index];        final product = items?.product;        final discountPrice = product?.discountPrice;        final price = product?.price;        final isRtl = context.isRtl;        return GestureDetector(          onTap: () {            kNavigationService.navigateTo(              AppRoutes.productDetails,              arguments: product?.id,            );          },          child: Stack(            children: [              Card(                color: AppColors.backgroundColor,                margin: REdgeInsets.all(15),                child: Padding(                  padding: const EdgeInsets.all(8.0),                  child: Row(                    children: [                      BuildImageAssets(                        url:                            "https://moccasin-manatee-172732.hostingersite.com/storage/products/1742696471_67df7017d7922.jpg",                        width: 150.w,                        height: 150.h,                      ),                      SizedBox(                          width: .3.sw,                          child: Column(                            spacing: 5,                            crossAxisAlignment: CrossAxisAlignment.start,                            children: [                              Text(                                product?.name ?? "",                                style: AppTextStyles.h5Bold,                                maxLines: 3,                              ),                              Text.rich(                                TextSpan(                                  text:                                      "${(discountPrice ?? price)!.split(".00").first}  ",                                  style: AppTextStyles.bodyMediumBold,                                  children: [                                    TextSpan(                                      text: discountPrice ?? "",                                      style: AppTextStyles.bodyXtraSmallSemiBold                                          .copyWith(                                              decoration:                                                  TextDecoration.lineThrough),                                    ),                                  ],                                ),                              ),                              items?.color == null                                  ? Container()                                  : Text.rich(                                      TextSpan(                                        text: "${local.Color}:",                                        style: AppTextStyles.bodyMediumBold,                                        children: [                                          TextSpan(                                            text: items?.color?.name ?? "",                                            style:                                                AppTextStyles.bodyMediumMedium,                                          ),                                        ],                                      ),                                    ),                              items?.size == null                                  ? Container()                                  : Text.rich(                                      TextSpan(                                        text: "${local.Size}:",                                        style: AppTextStyles.bodyMediumBold,                                        children: [                                          TextSpan(                                            text: items?.size?.name ?? "",                                            style:                                                AppTextStyles.bodyMediumMedium,                                          ),                                        ],                                      ),                                    ),                            ],                          )),                      Container(                        color: AppColors.primaryColor.withAlpha(100),                        height: 120.h,                        width: 1.w,                      ),                      Expanded(                          child: Column(                        mainAxisAlignment: MainAxisAlignment.center,                        children: [                          Text(items!.quantity.toString()),                          20.verticalSpace,                          Row(                            mainAxisAlignment: MainAxisAlignment.center,                            children: [                              IconButton(                                  onPressed: () {                                    if (items.quantity == 1) {                                      return;                                    } else {                                      context.read<CartCubit>().updateCartItems(                                            id: items.id,                                            newQuantity: items.quantity - 1,                                          );                                    }                                  },                                  icon: Icon(Icons.remove_circle)),                              IconButton(                                  onPressed: () {                                    context.read<CartCubit>().updateCartItems(                                          id: items.id,                                          newQuantity: items.quantity + 1,                                        );                                  },                                  icon: Icon(Icons.add_circle)),                            ],                          )                        ],                      ))                    ],                  ),                ),              ),              Positioned(                top: 0,                left: isRtl ? 0 : null,                right: isRtl ? null : 0,                child: IconButton(                  padding: REdgeInsets.only(                    top: 20.h,                    right: 25.w,                    left: 25.w,                  ),                  focusColor: Colors.transparent,                  autofocus: false,                  hoverColor: Colors.transparent,                  onHover: (value) => false,                  highlightColor: Colors.transparent,                  onPressed: () {                    context.read<CartCubit>().removeItems(id: items.id);                  },                  icon: const Icon(                    Icons.close,                    color: AppColors.primaryColor,                  ),                ),              )            ],          ),        );      }),    ]);  }}